import{_ as o,l as n,o as e,c as s,v as t,p as l,x as r,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"AGV 期望外部性","description":"","frontmatter":{"title":"AGV 期望外部性","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/agv-mechanism.md","filePath":"econ/agv-mechanism.md","lastUpdated":1789023840000}'),A={name:"econ/agv-mechanism.md"};function E(_,a,m,c,B,C){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="agv-期望外部性" tabindex="-1">AGV 期望外部性 <a class="header-anchor" href="#agv-期望外部性" aria-label="Permalink to &quot;AGV 期望外部性&quot;">​</a></h1><div class="epigraph"><p>每人支付自己对他人期望福利造成的外部性，则有效配置在贝叶斯激励相容下可实施，且转移可以事后预算平衡。</p><footer>—— d&#39;Aspremont and Gérard-Varet, Incentives and Incomplete Information, Journal of Public Economics, 1979；Arrow, The Property Rights Doctrine and Demand Revelation under Incomplete Information, 1979</footer></div><p><a href="/econ/myerson-satterthwaite">上一课</a>证明：事后有效、事中 IR、IC 与预算平衡不能一起要。缺口是：若放弃事中自愿参与，能否保住有效与平衡？AGV（期望外部性）给出肯定：转移不按枢轴的事后实现来收，而按「对他人类型取期望」的外部性来收。本课钉这条机制，不把无转移的匹配写成拍卖，也不重推 MS 的包络亏空。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公共品或双边交易，有效规则 \\(x^*(\\theta)=\\arg\\max_x\\sum_i v_i(x,\\theta_i)\\)。VCG / 克拉克枢轴：每人付自己给别人造成的<strong>事后</strong>福利差，占优策略 IC，但转移一般不平衡（设计者赤字）。AGV：给 \\(i\\) 的转移是</p> \\[t_i(\\hat\\theta_i)= \\mathbb{E}_{\\theta_{-i}}\\Bigl[\\sum_{j\\neq i} v_j\\bigl(x^*(\\hat\\theta_i,\\theta_{-i}),\\theta_j\\bigr)\\Bigr] + h_i(\\hat\\theta_{-i}), \\]<p>即 \\(i\\) 的报告通过 \\(x^*\\) 加在别人身上的<strong>期望</strong>外部性（外加只依赖别人报告的 \\(h_i\\)）。选 \\(h\\) 可使 \\(\\sum t_i=0\\) 对每一报告向量成立（事后预算平衡）。</p><p>贝叶斯 IC：在共同先验下，报真值最大化期望支付。不是占优策略——先验错了，IC 会坏。</p><h3 id="不与-ms-矛盾" tabindex="-1">不与 MS 矛盾 <a class="header-anchor" href="#不与-ms-矛盾" aria-label="Permalink to &quot;不与 MS 矛盾&quot;">​</a></h3><p>MS 要事中 IR。AGV 的期望支付对某些类型可以为负：高成本卖家、低估值买家可能「被有效规则强迫参加」，事中宁愿退出。事前 IR（对类型取期望后再比不参与）有时能满足，事中不能——这正是上一课缺口里被放松的那一条。</p><p><span class="marginnote">Arrow 与 d&#39;Aspremont–Gérard-Varet 独立给出期望外部性。课堂上 AGV 常对照 Groves：一个对每个 \\(v_{-i}\\) 都内部化（占优），一个只对分布内部化（贝叶斯）。平衡性来自「期望」把交叉项收成可抵消的 \\(h_i\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：准线性、共同先验、有限或紧类型空间。先取有效 \\(x^*\\)，再写期望 Groves 项，最后解 \\(h_i\\) 使预算恒等为零（若期望外部性之和已能写成可分离形式）。检验：偏离报告等于在错误的边际上最大化「自己的价值 + 别人的期望价值」，而真值才对齐社会目标的期望。</p>',13)),(e(),l(p,null,{default:r(()=>[d(i,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20MS%5B%22MS%EF%BC%9A%E5%9B%9B%E8%80%85%E4%B8%8D%E5%8F%AF%E5%85%BC%E5%BE%97%22%5D%20--%3E%20DROP%5B%22%E6%94%BE%E5%BC%83%E4%BA%8B%E4%B8%AD%20IR%22%5D%0A%20%20DROP%20--%3E%20AGV%5B%22%E6%9C%9F%E6%9C%9B%E5%A4%96%E9%83%A8%E6%80%A7%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20AGV%20--%3E%20BIC%5B%22%E8%B4%9D%E5%8F%B6%E6%96%AF%20IC%20%2B%20%E6%9C%89%E6%95%88%22%5D%0A%20%20AGV%20--%3E%20BB%5B%22%E5%8F%AF%E4%BA%8B%E5%90%8E%E9%A2%84%E7%AE%97%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20VCG%5B%22VCG%EF%BC%9A%E5%8D%A0%E4%BC%98%20IC%22%5D%20--%3E%20DEF%5B%22%E4%B8%80%E8%88%AC%E9%A2%84%E7%AE%97%E8%B5%A4%E5%AD%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>公共品、双边交易、团队生产，只要有效规则明确、先验共同，同一套转移。匹配下一课开始没有货币，\\(t\\) 写不出，AGV 用不上。双边交易教具：有效规则是 \\(v\\ge c\\) 则成交，期望外部性让买家承担「自己的报告如何改变卖方的期望剩余」，预算用 \\(h\\) 对冲；低 \\(v\\)、高 \\(c\\) 的类型事中可能为负，正是 MS 卡住的那些端点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>占优策略要求对每一对手报告都内部化，转移被钉得太死，加总留赤字。贝叶斯只要求对先验平均内部化，设计者多出一组 \\(h_i(\\theta_{-i})\\) 的自由度，正好用来平衡预算。代价是执行依赖「大家都按这个先验算期望」；先验不是共同知识时，AGV 的 IC 比 VCG 脆。</p><p>事中 IR 失败的几何：有效规则会让「不该交易」的报告组合仍按期望外部性付钱——极端类型承担了为别人的效率付账。MS 把这些人的事中支付托在保留效用之上，于是预算裂开。AGV 不托，预算能合上。</p><h3 id="团队与公共品是同一会计" tabindex="-1">团队与公共品是同一会计 <a class="header-anchor" href="#团队与公共品是同一会计" aria-label="Permalink to &quot;团队与公共品是同一会计&quot;">​</a></h3><p>团队里每人报边际产出，AGV 让每人承担对其余产出期望的影响，平衡时总奖金不靠老板贴钱。公共品里每人报 MRS，期望林达尔式转移可平衡，但低需求类型可能事中亏损——与「自愿贡献不足」不同：这里是强制规则加转移，不是纳什自愿供给。</p><p><span class="marginnote">若坚持占优策略 IC 又要平衡，一般只剩下无弹性的机制（Green–Laffont）。贝叶斯是换来平衡与有效的那一层。后课 Gale–Shapley 连转移都没有，解概念改成稳定，不再用 \\(t_i\\)。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>相关类型、没有共同先验、风险厌恶，期望外部性不必 IC。动态、重新谈判会把 \\(h_i\\) 的承诺掀掉。也不要把 AGV 写成宏观转移支付或限价簿手续费。</p><p>后课默认：放松事中 IR 之后，有效 + 贝叶斯 IC + 预算平衡可用 AGV 实施。下一课进入无货币的双边匹配：稳定配对，不再靠转移内部化外部性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MS 卡住是因为事中 IR；AGV 放弃它，保住有效与平衡。</li><li>转移按对他人的期望外部性来收，IC 是贝叶斯的，不是占优。</li><li>VCG 更强的 IC，一般不平衡；AGV 相反。</li><li>没有共同先验或没有货币时，这套转移写不出。</li><li>出处：d&#39;Aspremont and Gérard-Varet, <em>JPubE</em>, 1979；Arrow, 1979。</li></ul>',12))])}const G=o(A,[["render",E]]);export{u as __pageData,G as default};
